function clean(v){return String(v??'').trim()}
function yes(v){return ['TRUE','TAK','YES','1'].includes(clean(v).toUpperCase())}
function rows(name){
  try{return $(name).all().map(i=>i.json||{}).filter(r=>clean(r.Target_ID))}
  catch{return[]}
}

const tokenResponse=$('META — Get Virya Page Access Token').first().json||{};
if(tokenResponse.error){
  throw new Error(`Nie udało się pobrać Page Access Token: ${tokenResponse.error.message||JSON.stringify(tokenResponse.error)}`);
}

const pages=Array.isArray(tokenResponse.data)?tokenResponse.data:[];
const virya=pages.find(p=>
  clean(p.id)==='101848539107631' ||
  clean(p.instagram_business_account?.id)==='17841455886865962' ||
  clean(p.name).toLowerCase()==='virya'
);

if(!virya){
  throw new Error('Nie znaleziono strony Virya w /me/accounts.');
}
if(!clean(virya.access_token)){
  throw new Error('Meta nie zwróciła Page Access Token dla strony Virya.');
}
if(!clean(virya.instagram_business_account?.id)){
  throw new Error('Strona Virya nie ma powiązanego instagram_business_account.');
}

const all=rows('GS — META_TARGETS')
  .filter(r=>yes(r.Active))
  .filter(r=>!clean(r.Target_ID).startsWith('SEED-'))
  .filter(r=>clean(r.Platform)==='Instagram')
  .filter(r=>clean(r.Object_ID_or_Username))
  .filter(r=>['NEW','API_ERROR','PENDING',''].includes(clean(r.API_Status)))
  .sort((a,b)=>{
    const p={A:0,B:1,C:2};
    const retryA=clean(a.Last_Error).includes('Application does not have permission')?-1:0;
    const retryB=clean(b.Last_Error).includes('Application does not have permission')?-1:0;
    return retryA-retryB
      || (p[clean(a.Priority)]??9)-(p[clean(b.Priority)]??9)
      || clean(a.Last_Checked_At).localeCompare(clean(b.Last_Checked_At))
      || clean(a.Name).localeCompare(clean(b.Name));
  })
  .slice(0,5);

if(!all.length){
  return [{json:{
    __control:true,
    run_status:'OK_NO_INSTAGRAM_TARGETS',
    selected:0,
    note:'Brak aktywnych targetów Instagram. Uruchom ponownie VIRYA 15, aby doładować rejestr.'
  }}];
}

return all.map(r=>({
  json:{
    ...r,
    _page_access_token:clean(virya.access_token),
    _virya_ig_user_id:clean(virya.instagram_business_account.id),
    request_url:`https://graph.facebook.com/${clean(virya.instagram_business_account.id)}`,
    request_fields:`business_discovery.username(${clean(r.Object_ID_or_Username)}){id,username,name,biography,website,profile_picture_url,followers_count,follows_count,media_count,media.limit(5){id,caption,media_type,permalink,timestamp,like_count,comments_count}}`
  }
}));

function clean(v){return String(v??'').trim()}
function fnv(value){let h=2166136261;for(const ch of String(value)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}
function signals(text){
  const t=clean(text).toLowerCase();
  const words=['metal','rock','festival','koncert','concert','playlist','radio','podcast','review','recenz','premier','premiere','music','muzyka','band','zespół','reel','reaction'];
  return words.filter(w=>t.includes(w));
}
function money(text){
  const t=clean(text).toLowerCase();
  return ['sponsor','partner','ticket','bilet','booking','advert','reklam','paid','współprac','collab'].filter(w=>t.includes(w));
}
function email(text){
  return (clean(text).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'';
}
function score(target,text,engagement){
  let s={A:45,B:30,C:15}[clean(target.Priority)]||10;
  const sig=signals(text);
  s+=Math.min(35,sig.length*5);
  if(engagement>=100)s+=10;
  if(engagement>=1000)s+=5;
  return Math.min(100,s);
}

const responses=$input.all().map(i=>i.json||{});
const targets=$('Code — Select test batch').all().map(i=>i.json||{}).filter(r=>!r.__control);
const existing=new Set(
  $('GS — Existing META_ITEMS').all()
    .map(i=>clean(i.json?.Item_Key))
    .filter(Boolean)
);
const now=new Date().toISOString();
const out=[];

for(let i=0;i<targets.length;i++){
  const target=targets[i];
  const response=responses[i]||{};
  if(response.error)continue;

  if(clean(target.Platform)==='Instagram'){
    const profile=response.business_discovery;
    if(!profile)continue;
    for(const media of (profile.media?.data||[])){
      const key=`IG|${clean(media.id)}`;
      const itemKey=`METAITEM-${fnv(key)}`;
      if(existing.has(itemKey))continue;
      existing.add(itemKey);

      const text=clean(media.caption);
      const engagement=Number(media.like_count||0)+Number(media.comments_count||0);
      out.push({
        Item_Key:itemKey,
        Platform:'Instagram',
        Target_ID:target.Target_ID,
        Object_ID:clean(media.id),
        Permalink:clean(media.permalink),
        Published_At:clean(media.timestamp),
        Author_Name:clean(profile.name)||clean(profile.username)||clean(target.Name),
        Text:text,
        Media_Type:clean(media.media_type)||'MEDIA',
        Language:clean(target.Language)||'PL/EN',
        Country:clean(target.Country),
        Category_Hint:clean(target.Entity_Type),
        Money_Signals:money(text).join(', '),
        Fit_Signals:signals(`${profile.biography||''} ${text}`).join(', '),
        Contact_Email:email(`${profile.biography||''} ${profile.website||''} ${text}`),
        Contact_Phone:'',
        External_URL:clean(profile.website),
        Engagement:JSON.stringify({likes:Number(media.like_count||0),comments:Number(media.comments_count||0)}),
        Captured_At:now,
        Content_Hash:fnv(`${clean(media.id)}|${text}`),
        Score:score(target,`${profile.biography||''} ${text}`,engagement),
        Priority:clean(target.Priority)||'C',
        Status:'NEW',
        Raw_JSON_Link:''
      });
    }
  }else{
    const profile=response;
    for(const post of (profile.posts?.data||[])){
      const key=`FB|${clean(post.id)}`;
      const itemKey=`METAITEM-${fnv(key)}`;
      if(existing.has(itemKey))continue;
      existing.add(itemKey);

      const text=clean(post.message);
      const reactions=Number(post.reactions?.summary?.total_count||0);
      const comments=Number(post.comments?.summary?.total_count||0);
      const shares=Number(post.shares?.count||0);
      const engagement=reactions+comments+shares;
      out.push({
        Item_Key:itemKey,
        Platform:'Facebook',
        Target_ID:target.Target_ID,
        Object_ID:clean(post.id),
        Permalink:clean(post.permalink_url),
        Published_At:clean(post.created_time),
        Author_Name:clean(profile.name)||clean(target.Name),
        Text:text,
        Media_Type:post.full_picture?'POST_WITH_MEDIA':'POST',
        Language:clean(target.Language)||'PL/EN',
        Country:clean(target.Country),
        Category_Hint:clean(profile.category)||clean(target.Entity_Type),
        Money_Signals:money(text).join(', '),
        Fit_Signals:signals(`${profile.about||''} ${profile.description||''} ${text}`).join(', '),
        Contact_Email:clean((profile.emails||[])[0])||email(`${profile.about||''} ${profile.description||''} ${profile.website||''}`),
        Contact_Phone:'',
        External_URL:clean(profile.website),
        Engagement:JSON.stringify({reactions,comments,shares}),
        Captured_At:now,
        Content_Hash:fnv(`${clean(post.id)}|${text}`),
        Score:score(target,`${profile.about||''} ${profile.description||''} ${text}`,engagement),
        Priority:clean(target.Priority)||'C',
        Status:'NEW',
        Raw_JSON_Link:''
      });
    }
  }
}

if(!out.length)return[{json:{__control:true,has_items:false}}];
return out.map(json=>({json}));

function clean(v){return String(v??'').trim()}
function fnv(value){let h=2166136261;for(const ch of String(value)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}
function extractEmail(text){return (clean(text).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||''}
function profileScore(target,profileText,followers,posts){
  let s={A:45,B:30,C:15}[clean(target.Priority)]||10;
  const t=clean(`${target.Name} ${target.Entity_Type} ${profileText} ${posts}`).toLowerCase();
  const buckets=[
    ['metal',10],['rock',8],['festival',12],['radio',12],['podcast',10],
    ['playlist',12],['review',10],['recenz',10],['music',5],['muzyka',5],
    ['reaction',8],['premier',6],['creator',6],['magazine',8],['portal',8]
  ];
  for(const [word,pts] of buckets)if(t.includes(word))s+=pts;
  if(Number(followers)>=500)s+=5;
  if(Number(followers)>=2000)s+=5;
  return Math.min(100,s);
}
