    Gmail_Draft_ID:'',
    Gmail_Message_ID:'',
    Gmail_Thread_ID:'',
    Gmail_URL:'',
    Sent_At:'',
    Follow_Up_At:'',
    Reply_At:'',
    Reply_Summary:'',
    Reply_Class:'Brak',
    Next_Step:email
      ? 'Po akceptacji utworzyć Gmail draft'
      : `Po akceptacji wysłać ręcznie przez ${clean(t.Platform)}: ${profileUrl}`,
    Owner:'Virya Crew',
    Discord_Status:'Pending',
