function clean(v){return String(v??'').trim()}
const responses=$input.all().map(i=>i.json||{});
const targets=$('Code — Select test batch').all().map(i=>i.json||{}).filter(r=>!r.__control);
const now=new Date().toISOString();

let ok=0;
let errors=0;
let mediaSeen=0;
const errorDetails=[];

for(let i=0;i<targets.length;i++){
  const t=targets[i];
  const r=responses[i]||{};

  if(r.error){
    errors++;
    errorDetails.push({
      target:t.Target_ID,
      username:t.Object_ID_or_Username,
      message:r.error.message||JSON.stringify(r.error),
      code:r.error.code||null
    });
    continue;
  }

  if(!r.business_discovery){
    errors++;
    errorDetails.push({
      target:t.Target_ID,
      username:t.Object_ID_or_Username,
      message:'Brak business_discovery w odpowiedzi'
    });
    continue;
  }

  ok++;
  mediaSeen+=(r.business_discovery.media?.data||[]).length;
}

return [{json:{
  Run_Key:`META16IG:${now}`,
  Workflow:'VIRYA 16 — Instagram Business Discovery + Collaboration — TEST v2',
  Started_At:now,
  Finished_At:now,
  Status:errors&&ok?'PARTIAL_OK':errors?'API_ERROR':'OK',
  Input_Count:targets.length,
  Target_Count:targets.length,
  API_OK:ok,
  API_Errors:errors,
  New_Items:mediaSeen,
  Filtered_or_Duplicates:0,
  Notes:`Instagram test: targets=${targets.length}, API OK=${ok}, errors=${errors}, media seen=${mediaSeen}. Facebook pominięty — wymaga App Review.`,
  Execution_Mode:'manual-test',
  Trace_JSON:JSON.stringify({
    targets:targets.map(t=>({
      id:t.Target_ID,
      username:t.Object_ID_or_Username,
      name:t.Name
    })),
    errors:errorDetails
  }).slice(0,5000)
}}];

const j=$json;
return [{json:{
  send:Number(j.Input_Count||0)>0,
  content:`📸 **INSTAGRAM BUSINESS DISCOVERY — test v2**
Targets: ${j.Input_Count}
API OK: ${j.API_OK} | błędy: ${j.API_Errors}
Media widziane: ${j.New_Items}
Status: ${j.Status}

Facebook zewnętrzny jest chwilowo pominięty — wymaga Page Public Content/Metadata Access przez App Review.
Kandydaci trafiają do OUTREACH_LOG jako Pending. Nic nie jest wysyłane automatycznie.`
}}];
